const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || item.json;
const raw = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(body);
const secret = $env.N8N_WEBHOOK_SECRET || $env.ASF_WEBHOOK_SECRET;
const ts = headers['x-asf-timestamp'];
const sig = headers['x-asf-signature'];
if (!secret || !ts || !sig) throw new Error('Unauthorized');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${raw}`).digest('hex');
if (expected !== sig) throw new Error('Invalid signature');
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const key = body.idempotency_key || body.event_id;
if (staticData.seen[key]) {
  return [{ json: { duplicate: true, event: body } }];
}
staticData.seen[key] = Date.now();
if (!['scene.verification.completed','scene.real_generated','scene.uploaded'].includes(body.event_type)) {
  return [{ json: { duplicate: false, ignore: true, event: body } }];
}
return [{ json: { duplicate: false, ignore: false, event: body } }];

const status = $input.first().json;
const event = $('Validate + Dedupe').first().json.event;
const scene = (status.scenes || []).find(s => s.id === event.scene_id);
if (!scene) throw new Error('Scene missing in authoritative status');
const verified = (scene.state === 'REAL_GENERATED' || scene.state === 'READY_FOR_ASSEMBLY') && scene.asset_origin === 'REAL_GENERATED' && scene.has_durable_asset;
return [{ json: { verified, scene, status, event, resume_key: `${event.project_id}:${event.video_id}:${event.scene_id}` } }];
